D={
920015:("Presente contínuo: combinados","**Presente contínuo + tempo** fala de planos já combinados: *I'm meeting friends tonight.*",[("I'm {{meeting}} my boss.","Vou me encontrar com meu chefe."),("I'm {{busy}} on Sunday.","Estou ocupado no domingo."),("{{What are you doing}} on Saturday?","O que você vai fazer no sábado?"),("We're {{having}} a get-together tonight.","Vamos fazer uma reunião hoje à noite.")],"Qual frase combina um encontro?",["I'm meeting Ana tomorrow.","I met Ana tomorrow.","I meet Ana yesterday."],0,"Is/am/are + verbo-ing + tempo futuro = combinado."),
81106:("Advérbios de frequência","Vêm **antes do verbo**: *always, usually, often, rarely, never*.",[("I {{often}} walk to work.","Eu muitas vezes vou a pé ao trabalho."),("She {{always}} drinks water.","Ela sempre bebe água."),("I {{never}} skip breakfast.","Eu nunca pulo o café da manhã."),("He {{rarely}} eats sweets.","Ele raramente come doces.")],"Qual está certa?",["I drink always water.","I always drink water.","Always I drink water."],1,"O advérbio vem antes do verbo principal."),
81107:("during × for","**During** + evento (*during the game*); **for** + duração (*for two hours*).",[("I got hurt {{during}} the game.","Me machuquei durante o jogo."),("I rested {{for}} two weeks.","Descansei por duas semanas."),("My knee {{hurts}}.","Meu joelho dói."),("He broke his arm {{during}} practice.","Ele quebrou o braço durante o treino.")],"Complete: “We talked ___ three hours.”",["during","for","while"],1,"Duração em horas: for."),
81108:("Presente contínuo: agora","Para o que acontece **agora**: **am/is/are + verbo-ing**.",[("A fire {{is burning}}.","Há um incêndio em andamento."),("I {{am calling}} 911.","Estou ligando para o 911."),("A woman {{is}} hurt.","Uma mulher está ferida."),("{{What is your address}}?","Qual é o seu endereço?")],"Qual está certa?",["I call 911 now.","I'm calling 911 now.","I calling 911 now."],1,"Agora: am + verbo-ing."),
81109:("Plurais irregulares","Alguns plurais fogem do -s: **tooth → teeth, foot → feet, child → children**.",[("Brush your {{teeth}} twice a day.","Escove os dentes duas vezes ao dia."),("You have one {{cavity}}.","Você tem uma cárie."),("Use {{floss}} every night.","Use fio dental toda noite."),("My {{feet}} hurt.","Meus pés doem.")],"Qual é o plural de “tooth”?",["tooths","teeth","teeths"],1,"Tooth → teeth."),
81110:("had better (not)","**Had better** é aviso forte; **had better not** proíbe.",[("You {{had better}} read the label.","É melhor você ler o rótulo."),("You {{had better not}} drink it.","É melhor você não beber isso."),("Take it {{with food}}.","Tome com comida."),("Keep it {{away from children}}.","Mantenha longe de crianças.")],"“You had better not” indica…",["permissão","aviso para evitar","convite"],1,"Had better not = melhor não fazer."),
81111:("Comparativos","Junte **-er + than**: *heavier than, lighter than, stronger than*.",[("This weight is {{heavier than}} that one.","Este peso é mais pesado que aquele."),("I feel {{stronger}} every month.","Eu me sinto mais forte a cada mês."),("He runs {{faster than}} me.","Ele corre mais rápido que eu."),("I'm {{more tired than}} yesterday.","Estou mais cansado que ontem.")],"Qual é o comparativo de “heavy”?",["heavyer","heavier","more heavy"],1,"Heavy → heavier."),
81112:("required / optional","**Required** = obrigatório; **optional** = opcional.",[("A degree is {{required}}.","Diploma é obrigatório."),("Experience is {{optional}}.","Experiência é opcional."),("Please {{apply}} online.","Candidate-se on-line."),("Send your {{resume}} by email.","Envie seu currículo por e-mail.")],"“Optional” significa…",["obrigatório","opcional","proibido"],1,"Optional = opcional."),
920016:("Sugestões","**How about** + verbo-ing; **why don't we** e **let's** + verbo base.",[("{{Why don't we}} split up now?","Por que não nos separamos agora?"),("{{Let's}} look for a clue.","Vamos procurar uma pista."),("{{How about}} looking behind the door?","Que tal olhar atrás da porta?"),("{{Why don't we}} use the flashlight?","Por que não usamos a lanterna?")],"Qual está certa?",["How about look?","How about looking?","How about to look?"],1,"How about + verbo-ing."),
81113:("Present perfect","Para experiência: **have/has + particípio**. *I have worked in sales.*",[("I {{have worked}} in sales.","Já trabalhei em vendas."),("She {{has worked}} here for years.","Ela trabalha aqui há anos."),("I work well {{in a team}}.","Trabalho bem em equipe."),("My biggest {{strength}} is honesty.","Meu maior ponto forte é a honestidade.")],"Complete: “She ___ worked here.”",["have","has","is"],1,"She pede has."),
81114:("at + horário","Use **at** com horas. Presente simples para rotina: *I start at eight.*",[("I start work {{at eight}}.","Começo a trabalhar às oito."),("I finish {{at five}}.","Termino às cinco."),("We eat {{at noon}}.","Almoçamos ao meio-dia."),("He has a {{break}} at ten.","Ele faz uma pausa às dez.")],"Complete: “The meeting is ___ nine.”",["in","on","at"],2,"Horas pedem at."),
81115:("How about / Let's","Para sugerir: **How about + verbo-ing?** ou **Let's + verbo**.",[("{{How about}} talking first?","Que tal conversarmos primeiro?"),("{{Let's}} vote now.","Vamos votar agora."),("{{I agree}} with you.","Concordo com você."),("{{How about}} moving the meeting?","Que tal mudar a reunião?")],"Qual sugestão está certa?",["How about meet?","Let's meet.","Let's meeting."],1,"Let's + verbo base."),
81116:("E-mail simples","Estrutura: **Dear + nome**, mensagem, **Best regards + nome**.",[("{{Dear}} Theo,","Caro Theo,"),("The file is {{attached}}.","O arquivo está anexado."),("{{Best regards}}, Vincent","Atenciosamente, Vincent"),("Please {{reply}} soon.","Responda logo, por favor.")],"Como se fecha um e-mail formal?",["Bye bye","Best regards","See you"],1,"Best regards é o fecho padrão."),
81117:("May I / Could you","Pedidos educados: **May I…?** e **Could you…?**",[("{{May I}} speak to Ann?","Posso falar com a Ann?"),("{{Could you}} hold, please?","Você poderia aguardar na linha?"),("I'll {{transfer}} your call.","Vou transferir sua ligação."),("{{May I}} leave a message?","Posso deixar um recado?")],"Qual é mais educado?",["I want Ann.","May I speak to Ann?","Give me Ann."],1,"May I? é cortês."),
81118:("by × until","**By** = prazo (até lá, no máximo). **Until** = durante todo o tempo até.",[("Send it {{by}} Friday.","Envie até sexta."),("I'll work {{until}} six.","Vou trabalhar até as seis."),("The {{deadline}} is Monday.","O prazo é segunda."),("Finish it {{by}} tomorrow.","Termine até amanhã.")],"“Send it by Friday” quer dizer…",["Envie até sexta, no máximo.","Envie só depois de sexta.","Envie toda sexta."],0,"By marca o prazo final."),
81119:("Do you mind…?","**Do you mind + verbo-ing?** é um pedido educado. Resposta: *No, not at all.*",[("{{Do you mind helping}} me?","Você se importa de me ajudar?"),("{{No, not at all}}.","De jeito nenhum."),("{{Can you check}} my report?","Pode conferir meu relatório?"),("Can I ask {{a favor}}?","Posso pedir um favor?")],"Resposta que aceita “Do you mind?”",["Yes, I do.","No, not at all.","I mind."],1,"No, not at all = aceito de bom grado."),
920017:("some / any / a lot of","**Some** nas positivas; **any** em perguntas e negativas; **a lot of** em todas.",[("I have {{some}} chocolate.","Tenho um pouco de chocolate."),("Is there {{any}} candy left?","Sobrou algum doce?"),("There is {{a lot of}} candy.","Há muito doce."),("We don't have {{any}} jelly beans.","Não temos jelly beans.")],"Complete: “I don't have ___ sweets.”",["some","any","a lot"],1,"Na negativa: any."),
81121:("Can I / May I","Pedir permissão: **Can I…?** (comum) ou **May I…?** (formal).",[("{{Can I}} have a day off?","Posso tirar um dia de folga?"),("{{May I}} leave early today?","Posso sair mais cedo hoje?"),("I have an {{appointment}}.","Tenho um compromisso."),("{{Can I}} ask you something?","Posso perguntar uma coisa?")],"Qual é o mais formal?",["Can I go?","May I go?","I go?"],1,"May I é mais formal."),
81122:("on / in / at (tempo)","**On** com dias e datas; **in** com meses; **at** com horas.",[("I want to {{book}} a flight.","Quero reservar um voo."),("It leaves {{on}} June 5th.","Parte em 5 de junho."),("It leaves {{at}} 8 a.m.","Parte às 8 da manhã."),("We travel {{in}} June.","Viajamos em junho.")],"Complete: “The flight is ___ Monday.”",["in","on","at"],1,"Dia da semana: on."),
81123:("Would you like…?","Para oferecer: **Would you like…?** Aceitar: *Yes, please.*",[("{{I'd like to}} check in.","Gostaria de fazer o check-in."),("{{Here is}} your boarding pass.","Aqui está seu cartão de embarque."),("{{Would you like}} a window seat?","Quer um assento na janela?"),("Yes, {{please}}.","Sim, por favor.")],"Como aceitar uma oferta?",["Yes, please.","Yes, I want.","No, please."],0,"Yes, please aceita com educação."),
81124:("lost / left","Passados irregulares: **lose → lost**, **leave → left**.",[("I {{lost}} my suitcase.","Perdi minha mala."),("I {{left}} it on the plane.","Deixei no avião."),("Please {{fill out}} this form.","Preencha este formulário."),("Can you {{describe}} it?","Pode descrevê-la?")],"Qual é o passado de “lose”?",["losed","lost","loss"],1,"Lose → lost."),
81125:("Verbos com partículas","**Take off** (tirar/decolar), **turn off** (desligar), **put on** (vestir).",[("Please {{take off}} your shoes.","Tire os sapatos, por favor."),("{{Turn off}} your phone, please.","Desligue o celular, por favor."),("{{Fasten}} your seat belt.","Aperte o cinto."),("The plane will {{take off}} soon.","O avião vai decolar em breve.")],"“Turn off” significa…",["ligar","desligar","tirar"],1,"Turn off = desligar."),
81126:("will be + particípio","Futuro com passivo: **will be + particípio**. *The flight will be delayed.*",[("Your flight {{will be delayed}}.","Seu voo será atrasado."),("Please {{wait}} at the gate.","Aguarde no portão."),("We {{apologize}} for the delay.","Pedimos desculpas pelo atraso."),("The gate {{will be changed}}.","O portão será mudado.")],"“Will be delayed” fala de…",["um voo adiantado","um voo atrasado","um voo cancelado"],1,"Delayed = atrasado."),
920018:("Ao telefone","Frases comuns: **hold on** (esperar na linha), **hang up** (desligar), **call back** (retornar).",[("{{Hold on}} a minute.","Espere um minuto."),("Can I {{take a message}}?","Posso anotar um recado?"),("Don't {{hang up}} now.","Não desligue agora."),("I'll {{call back}} later.","Retorno a ligação depois.")],"“Hang up” significa…",["ligar","desligar","esperar"],1,"Hang up = desligar o telefone."),
81127:("for + noites","**For** + duração: *a room for three nights*. Preço: **per night**.",[("I want a room {{for two nights}}.","Quero um quarto por duas noites."),("I'd like a {{single}} room.","Gostaria de um quarto de solteiro."),("It's eighty dollars {{per night}}.","São oitenta dólares por noite."),("{{When}} do I check out?","Quando faço o check-out?")],"Como dizer “por três noites”?",["for three nights","in three nights","at three nights"],0,"Duração: for."),
81128:("Could you / Is there","**Could you** pede um favor; **Is there** pergunta se existe.",[("{{Could you}} call a taxi?","Você poderia chamar um táxi?"),("{{Is there}} Wi-Fi in the room?","Há Wi-Fi no quarto?"),("{{Is breakfast}} included?","O café da manhã está incluído?"),("{{Could you}} give me the key?","Poderia me dar a chave?")],"Qual pergunta pede um favor?",["Is there a taxi?","Could you call a taxi?","Where taxi?"],1,"Could you + verbo pede ajuda."),
81129:("There is no / doesn't work","Para reclamar: **There is no…** (não há) ou **It doesn't work** (não funciona).",[("{{There is no}} hot water.","Não há água quente."),("The TV {{doesn't work}}.","A TV não funciona."),("The air conditioner is {{broken}}.","O ar-condicionado está quebrado."),("Please {{send someone}}.","Mande alguém, por favor.")],"Complete: “The lamp ___ work.”",["don't","doesn't","isn't"],1,"The lamp (= it): doesn't."),
81130:("How far / How long","**How far** pergunta a distância; **how long** pergunta o tempo.",[("{{How far}} is the museum?","A que distância fica o museu?"),("{{How long}} is the tour?","Quanto dura o passeio?"),("Can I have {{a map}}?","Posso pegar um mapa?"),("It's a ten-minute {{walk}}.","São dez minutos a pé.")],"“How long is the trip?” pergunta…",["a distância","a duração","o preço"],1,"How long = quanto tempo."),
81131:("How much / How many","**How much** com o que não se conta (*money, gas*); **how many** com o que se conta (*days, cars*).",[("{{How much}} is the car?","Quanto custa o carro?"),("{{How many}} days do you need?","De quantos dias você precisa?"),("It's fifty dollars {{per day}}.","São cinquenta dólares por dia."),("Return it with a {{full}} tank.","Devolva com o tanque cheio.")],"Complete: “How ___ cars do you have?”",["much","many","long"],1,"Cars se contam: many."),
81132:("must / have to","**Must** = obrigação forte; **have to** = obrigação por regra; **don't have to** = não precisa.",[("You {{must}} wear a seatbelt.","Você deve usar cinto."),("We {{have to}} follow the rules.","Temos de seguir as regras."),("The {{speed limit}} is sixty-five.","O limite de velocidade é sessenta e cinco."),("You {{don't have to}} drive fast.","Você não precisa dirigir rápido.")],"“You don't have to” significa…",["é proibido","não é preciso","é obrigatório"],1,"Don't have to = não precisa."),
81133:("Direções","**Turn left/right, go straight, next to, across from.**",[("{{Turn left}} at the corner.","Vire à esquerda na esquina."),("{{Go straight}} for two blocks.","Siga em frente por dois quarteirões."),("The bank is {{across from}} the park.","O banco fica em frente ao parque."),("It's {{next to}} the bakery.","Fica ao lado da padaria.")],"“Across from” significa…",["ao lado de","em frente a","atrás de"],1,"Across from = do outro lado, em frente."),
920019:("so / such a","**So** vem antes de adjetivo; **such a** vem antes de substantivo.",[("That is {{so}} cool!","Isso é tão legal!"),("It is {{such a}} fun trend.","É uma tendência muito divertida."),("He is {{so}} funny.","Ele é tão engraçado."),("She is {{such a}} good friend.","Ela é uma ótima amiga.")],"Complete: “It's ___ nice day.”",["so","such a","too"],1,"Antes de substantivo (day): such a."),
81134:("get on / get off","Em transporte público: **get on** (subir) e **get off** (descer).",[("{{Where do I get on}}?","Onde eu subo?"),("{{Get on}} the bus.","Suba no ônibus."),("{{Get off}} at Main Street.","Desça na Main Street."),("The {{fare}} is two dollars.","A passagem custa dois dólares.")],"“Get off” significa…",["subir","descer","esperar"],1,"Get off = descer."),
81135:("this / that / these / those","**This/these** = perto; **that/those** = longe.",[("{{This}} bag is handmade.","Esta bolsa é artesanal."),("How much are {{those}} cups?","Quanto custam aqueles copos?"),("{{These}} postcards are pretty.","Estes cartões são bonitos."),("I want {{that}} souvenir.","Quero aquela lembrança.")],"Complete: “___ shoes here are nice.” (perto, plural)",["This","These","Those"],1,"Perto e plural: these."),
81136:("How much / How many","Informações de viagem: **How much is the ticket?** **How many hours is the trip?**",[("{{How much}} is the ticket?","Quanto custa a passagem?"),("{{How many}} hours is the trip?","Quantas horas dura a viagem?"),("The train leaves from {{platform}} two.","O trem sai da plataforma dois."),("{{All aboard}}!","Todos a bordo!")],"Complete: “How ___ is a ticket?”",["many","much","long"],1,"Preço: how much."),
81137:("Let's / Why don't we","Sugerir: **Let's + verbo** ou **Why don't we + verbo?**",[("{{Let's}} hit the road.","Vamos pegar a estrada."),("{{Why don't we}} drive tonight?","Por que não dirigimos hoje à noite?"),("We {{need}} to buy gas.","Precisamos comprar gasolina."),("{{Let's}} pick a route.","Vamos escolher uma rota.")],"Qual é uma sugestão?",["Let's go!","We lets go.","Go let's."],0,"Let's + verbo."),
81138:("need to / don't need to","**Need to** = precisa; **don't need to** = não precisa.",[("We {{need}} a tent.","Precisamos de uma barraca."),("You {{need to}} bring water.","Você precisa trazer água."),("You {{don't need}} a flashlight today.","Hoje você não precisa de lanterna."),("Put it in your {{backpack}}.","Ponha na sua mochila.")],"“Don't need to” quer dizer…",["não precisa","é proibido","deve"],0,"Não é necessário."),
81139:("should / shouldn't","**Should** = é bom fazer; **shouldn't** = não é bom.",[("You {{should}} wear a hat.","Você deveria usar chapéu."),("You {{shouldn't}} swim alone.","Você não deveria nadar sozinho."),("{{Put on}} sunscreen.","Passe protetor solar."),("You {{should}} bring a towel.","Você deveria levar toalha.")],"Complete: “You ___ swim after eating.” (não é bom)",["should","shouldn't","must"],1,"Não é bom: shouldn't."),
920020:("Segredos","*Spill the beans* = revelar um segredo. *Keep a secret* = guardar segredo.",[("Don't {{spill the beans}}!","Não conte o segredo!"),("I can {{keep a secret}}.","Sei guardar segredo."),("I'll tell {{the truth}} today.","Vou dizer a verdade hoje."),("It's {{classified}}.","É confidencial.")],"“Spill the beans” significa…",["derrubar feijão","revelar um segredo","cozinhar"],1,"É uma expressão para revelar segredos."),
81141:("must / mustn't","Regras: **must** = deve; **mustn't** = é proibido.",[("You {{must}} be quiet after ten.","Você deve ficar em silêncio depois das dez."),("You {{mustn't}} eat in the room.","Você não deve comer no quarto."),("Put your bag in the {{locker}}.","Guarde sua mochila no armário."),("You {{must}} share the bathroom.","Você deve dividir o banheiro.")],"“You mustn't smoke” quer dizer…",["Pode fumar.","É proibido fumar.","Precisa fumar."],1,"Mustn't = proibição."),
}
